computeFn:
const bill = Number(billAmount) || 0;
const tipPct = (Number(tipPercent) || 0) / 100;
const people = Number(splitPeople) || 1;
const taxPct = (Number(taxRatePct) || 0) / 100;
const tax = bill * taxPct;
const tip = bill * tipPct;
const total = bill + tax + tip;
const perPerson = people > 0 ? total / people : total;
const tipRate = tipPct * 100;
return { tipRate, perPerson, total, tip };
